"""Shot lists for the video craft tests, built from stated parameters (PRD 2026-10-19 §1.1 item 5).

Not a test module (no ``test_`` prefix). It imports nothing from ``gtm_core.video_craft`` at module
level, so a test that imports it still collects in the public cut, where that package is withheld.

Every product, scene description and word here is fictional. Two things are isolated in every
caller through :func:`isolate`, because both read state another process may be changing:

* ``motion.recorded_classes`` reads ``motion_classes.toml``, which is regenerated by measurement;
  the tests pin their OWN table (``STUB_CLASSES``) and never assert a real scene's class.
* ``design_system.load_kit`` reads the developer's active profile; the tests hand it a kit.
"""

from __future__ import annotations

import copy

#: The motion table the tests run against. Real registered scene NAMES (so a registry check
#: would accept them), but classes chosen by the test, one per motion class.
STUB_CLASSES: dict[str, str] = {
    "html:diagram-reveal": "moving",
    "html:kinetic-type": "settling",
    "pillow:still-push": "static",
    "pillow:checkpoint-flow": "static",
}

#: A design-system policy that rules nothing out, so ``design system: not set`` never appears.
CLEAN_KIT: dict = {
    "design_system": {
        "archetype": "editorial-light",
        "background_plates_in_ui": True,
        "allow_3d_canvas_in_video": True,
        "accent_as_fill": True,
        "denied_fonts": [],
        "denied_hexes": [],
    }
}

RATIO = "16:9"


def isolate(monkeypatch, *, kit: object = CLEAN_KIT, classes: dict[str, str] | None = None) -> None:
    """Pin the motion table and the brand kit, and clear the runtime and HTML switches."""
    from gtm_core.video_craft import design_system, motion

    table = dict(STUB_CLASSES if classes is None else classes)
    monkeypatch.delenv("GTM_RUNTIME", raising=False)
    monkeypatch.delenv("GTM_SCREEN_UI_HTML_ENABLED", raising=False)
    monkeypatch.setattr(motion, "recorded_classes", lambda: dict(table))
    monkeypatch.setattr(design_system, "load_kit", lambda: copy.deepcopy(kit))


def words(count: int) -> str:
    """``count`` distinct one-token words."""
    return " ".join(f"tok{i}" for i in range(count))


def shot(
    n: int,
    asset_class: str | None,
    duration: float,
    *,
    role: str = "broll",
    scene: str | None = None,
    backend: str | None = None,
    overlay_words: int = 0,
    visual: str = "a plain fictional frame",
    **extra: object,
) -> dict:
    """One shot. ``asset_class=None`` leaves the ``asset`` block out entirely."""
    out: dict = {"n": n, "role": role, "duration_s": duration, "visual": visual}
    if asset_class is not None:
        out["asset"] = {"class": asset_class}
    production: dict = {}
    if scene is not None:
        screen_ui: dict = {"scene": scene}
        if backend is not None:
            screen_ui["backend"] = backend
        # No `diagram` file: the fixtures judge structure. Counting a drawing's own labels needs
        # a real file and is tested on its own (test_a_diagram_whose_labels_exceed_the_ceiling_warns).
        production["screen_ui"] = screen_ui
    if overlay_words:
        production["overlay"] = [{"text": words(overlay_words)}]
    if production:
        out["production"] = production
    out.update(extra)
    return out


def doc(shots: list[dict], *, ratios: list[str] | None = None) -> dict:
    return {
        "total_duration_s": sum(
            s["duration_s"] for s in shots if isinstance(s.get("duration_s"), int | float)
        ),
        "deliverable_ratios": [RATIO] if ratios is None else ratios,
        "shots": shots,
    }


def good(ceiling: int) -> dict:
    """Every rule satisfied: a presenter, a diagram-reveal shot at exactly the word ceiling, one
    shot per stubbed motion class (moving, settling, static), and filmed b-roll."""
    return doc(
        [
            shot(1, "presenter", 4.0, role="presenter"),
            shot(
                2,
                "diagram",
                5.0,
                scene="diagram-reveal",
                backend="html",
                overlay_words=ceiling,
            ),
            shot(3, "kinetic_type", 3.0, scene="kinetic-type", backend="html", overlay_words=2),
            shot(4, "ui_mock", 3.0, scene="still-push", overlay_words=1),
            shot(5, "photo_broll", 4.0),
        ]
    )


#: ``bad_all``: the cuts each rule must name (listed, not derived, so the test states them).
BAD_ALL_DIAGRAM_CUTS = (1, 2, 3, 5, 6, 8, 9, 11, 12)
BAD_ALL_OVER_WORDS = (2, 5, 7, 9, 13)
BAD_ALL_NO_CLASS = (4, 10)
BAD_ALL_KINETIC = (7, 13)
BAD_ALL_PRESENTER = (14,)


def bad_all(ceiling: int) -> dict:
    """A dense 14-cut explainer: every diagram on a still scene, five cuts over the word ceiling,
    two with no kind of picture."""
    shots: list[dict] = []
    for n in range(1, 15):
        over = ceiling + 3 if n in BAD_ALL_OVER_WORDS else 1
        if n in BAD_ALL_DIAGRAM_CUTS:
            shots.append(shot(n, "diagram", 4.0, scene="checkpoint-flow", overlay_words=over))
        elif n in BAD_ALL_NO_CLASS:
            shots.append(shot(n, None, 4.0))
        elif n in BAD_ALL_KINETIC:
            shots.append(
                shot(
                    n, "kinetic_type", 4.0, scene="kinetic-type", backend="html", overlay_words=over
                )
            )
        else:
            shots.append(shot(n, "presenter", 4.0, role="presenter"))
    return doc(shots)


def static_share(document: dict) -> float:
    """Static seconds over summed shot durations, read off the stub table (the test's own sum)."""
    total = 0.0
    still = 0.0
    for s in document["shots"]:
        total += s["duration_s"]
        ui = (s.get("production") or {}).get("screen_ui")
        if ui is None:
            continue
        key = f"{ui.get('backend') or 'pillow'}:{ui['scene']}"
        if STUB_CLASSES.get(key) == "static":
            still += s["duration_s"]
    return still / total
